begin;
-- Explicit publication records are deliberately separate from runtime deployment
-- projects, which contain private environment/configuration/operations metadata.
create table if not exists cbgpu_schools.public_project_profiles(
 id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id),source_project_id uuid references public.cpu_projects(id),school_id text references cbgpu_schools.schools(id),
 slug text not null unique check(slug ~ '^[a-z0-9][a-z0-9-]{1,78}[a-z0-9]$'),title text not null,summary text not null default '',body_markdown text not null default '',
 visibility text not null default 'PRIVATE' check(visibility in('PRIVATE','SCHOOL','AUTHENTICATED','PUBLIC')),status text not null default 'DRAFT' check(status in('DRAFT','PUBLISHED')),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
alter table cbgpu_schools.public_project_profiles enable row level security;
revoke all on cbgpu_schools.public_project_profiles from public,anon,authenticated;
-- Existing nationwide messages remain login-only. No old post becomes public.
alter table cbgpu_schools.messages drop constraint if exists messages_scope_check;
alter table cbgpu_schools.messages add constraint messages_scope_check check(scope in('SCHOOL','NATIONWIDE','AUTHENTICATED','PUBLIC'));
create or replace function cbgpu_schools.community_allowed(uid uuid,scope text,school text) returns boolean language sql stable security definer set search_path='' as $$select case when scope='SCHOOL' then cbgpu_schools.active_member(uid,school) and exists(select 1 from cbgpu_schools.schools s where s.id=school and 'community'=any(s.features)) when scope in('PUBLIC','AUTHENTICATED') then school is null and exists(select 1 from public.profiles identity_profile join auth.users u on u.id=identity_profile.id where identity_profile.id=uid and identity_profile.account_status<>'SUSPENDED' and u.email_confirmed_at is not null and u.deleted_at is null and(u.banned_until is null or u.banned_until<=now())) when scope='NATIONWIDE' then school is null and exists(select 1 from cbgpu_schools.memberships m join cbgpu_schools.schools s on s.id=m.school_id where m.user_id=uid and cbgpu_schools.active_member(uid,m.school_id) and 'community'=any(s.features)) else false end$$;
create or replace function cbgpu_schools.public_project(p cbgpu_schools.public_project_profiles) returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object('id',p.id,'slug',p.slug,'title',p.title,'summary',p.summary,'body_markdown',p.body_markdown,'school_id',p.school_id,'created_at',p.created_at,'updated_at',p.updated_at)$$;
create or replace function cbgpu_schools.public_contest(c public.contests) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',c.id,'title',c.title,'description',c.description,'banner_path',c.banner_path,'school_id',c.school_id,'event_start_at',c.event_start_at,'event_end_at',c.event_end_at,'registration_open',c.registration_open,'registration_closes_at',c.registration_closes_at,'location_type',c.location_type,'location_name',c.location_name,'lifecycle_status',c.lifecycle_status,'participation_mode',c.participation_mode,'team_min_size',c.team_min_size,'team_max_size',c.team_max_size,'created_at',c.created_at)$$;
create or replace function public.cbgpu_public_content(action text,payload jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path='' as $$declare lim integer:=least(100,greatest(1,coalesce((payload->>'limit')::integer,30)));off integer:=greatest(0,coalesce((payload->>'offset')::integer,0));q text:=left(coalesce(payload->>'query',''),150);item jsonb;begin
 if action='projects_list' then return jsonb_build_object('items',(select coalesce(jsonb_agg(cbgpu_schools.public_project(x) order by x.updated_at desc),'[]') from(select p.* from cbgpu_schools.public_project_profiles p where visibility='PUBLIC' and status='PUBLISHED' and(title ilike '%'||q||'%' or summary ilike '%'||q||'%') order by updated_at desc limit lim offset off)x),'total',(select count(*) from cbgpu_schools.public_project_profiles where visibility='PUBLIC' and status='PUBLISHED' and(title ilike '%'||q||'%' or summary ilike '%'||q||'%')));end if;
 if action='project' then select cbgpu_schools.public_project(p) into item from cbgpu_schools.public_project_profiles p where(p.id::text=payload->>'id' or p.slug=payload->>'id') and p.visibility='PUBLIC' and p.status='PUBLISHED';return jsonb_build_object('item',item);end if;
 if action='contests_list' then return jsonb_build_object('items',(select coalesce(jsonb_agg(cbgpu_schools.public_contest(x) order by x.created_at desc),'[]') from(select c.* from public.contests c where c.access_scope='PUBLIC' and c.lifecycle_status='published' and c.title ilike '%'||q||'%' order by c.created_at desc limit lim offset off)x),'total',(select count(*) from public.contests c where c.access_scope='PUBLIC' and c.lifecycle_status='published' and c.title ilike '%'||q||'%'));end if;
 if action='contest' then select cbgpu_schools.public_contest(c) into item from public.contests c where c.id::text=payload->>'id' and c.access_scope='PUBLIC' and c.lifecycle_status='published';return jsonb_build_object('item',item);end if;
 if action='messages_list' then return jsonb_build_object('items',(select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'body',x.body,'created_at',x.created_at,'scope','PUBLIC') order by x.created_at desc),'[]') from(select * from cbgpu_schools.messages where scope='PUBLIC' and deleted_at is null and body ilike '%'||q||'%' order by created_at desc limit lim offset off)x),'total',(select count(*) from cbgpu_schools.messages where scope='PUBLIC' and deleted_at is null and body ilike '%'||q||'%'));end if;
 if action='schools_list' then return public.cbgpu_school_api('directory',jsonb_build_object('q',q,'limit',lim,'offset',off));end if;
 if action='school' then return jsonb_build_object('item',(select cbgpu_schools.summary(s) from cbgpu_schools.schools s where s.id=payload->>'id' and s.status in('APPROVED','LISTED','UNCLAIMED')));end if;
 raise exception 'UNKNOWN_PUBLIC_CONTENT_ACTION' using errcode='23514';end$$;
revoke all on function public.cbgpu_public_content(text,jsonb) from public;grant execute on function public.cbgpu_public_content(text,jsonb) to anon,authenticated;
-- Authenticated explicit publication, never ambient public writer access.
create or replace function public.cbgpu_public_project_api(action text,payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=auth.uid();p cbgpu_schools.public_project_profiles;sid text:=nullif(payload->>'school_id','');source uuid:=nullif(payload->>'source_project_id','')::uuid;begin
 if uid is null or not cbgpu_accounts.current_session_valid() or not exists(select 1 from public.profiles identity_profile join auth.users u on u.id=identity_profile.id where identity_profile.id=uid and identity_profile.account_status<>'SUSPENDED' and u.deleted_at is null and(u.banned_until is null or u.banned_until<=now())) then raise exception 'AUTHENTICATION_REQUIRED' using errcode='42501';end if;
 if action='list' then return jsonb_build_object('items',(select coalesce(jsonb_agg(to_jsonb(x) order by updated_at desc),'[]') from cbgpu_schools.public_project_profiles x where owner_id=uid));end if;
 if action='save' then
 if coalesce(length(btrim(payload->>'title')),0) not between 1 and 150 or coalesce(length(payload->>'summary'),0)>1000 or coalesce(length(payload->>'body_markdown'),0)>30000 or coalesce(payload->>'slug','') !~ '^[a-z0-9][a-z0-9-]{1,78}[a-z0-9]$' or coalesce(payload->>'visibility','PRIVATE') not in('PRIVATE','SCHOOL','AUTHENTICATED','PUBLIC') then raise exception 'INVALID_PUBLICATION';end if;
 if sid is not null and not cbgpu_schools.active_member(uid,sid) then raise exception 'SCHOOL_PUBLICATION_PERMISSION_REQUIRED' using errcode='42501';end if;
 if source is not null and not exists(select 1 from public.cpu_projects where id=source and user_id=uid) then raise exception 'PROJECT_NOT_FOUND' using errcode='P0002';end if;
 if payload->>'id' is null then insert into cbgpu_schools.public_project_profiles(owner_id,slug,title,summary,body_markdown,school_id,source_project_id) values(uid,payload->>'slug',btrim(payload->>'title'),coalesce(payload->>'summary',''),coalesce(payload->>'body_markdown',''),sid,source) returning * into p;
 else select * into p from cbgpu_schools.public_project_profiles where id=(payload->>'id')::uuid and owner_id=uid for update;if not found then raise exception 'PROJECT_NOT_FOUND' using errcode='P0002';end if;end if;
 update cbgpu_schools.public_project_profiles set slug=payload->>'slug',title=btrim(payload->>'title'),summary=coalesce(payload->>'summary',''),body_markdown=coalesce(payload->>'body_markdown',''),school_id=sid,source_project_id=source,visibility=coalesce(payload->>'visibility','PRIVATE'),status=case when payload->>'visibility'='PUBLIC' and payload->'confirmed'='true'::jsonb then 'PUBLISHED' else 'DRAFT' end,updated_at=now() where id=p.id returning * into p;return jsonb_build_object('project',to_jsonb(p));
 end if;raise exception 'UNKNOWN_PUBLICATION_ACTION';end$$;
revoke all on function public.cbgpu_public_project_api(text,jsonb) from public,anon;grant execute on function public.cbgpu_public_project_api(text,jsonb) to authenticated;
revoke all on function cbgpu_schools.public_project(cbgpu_schools.public_project_profiles),cbgpu_schools.public_contest(public.contests) from public,anon,authenticated;
commit;
